// Validation against the frozen Python reference table (tests/refdata/core.json,
// generated by tests/gen_ref_tables.py).
//
// Sections whose Python implementation is pure IEEE arithmetic, exact rational
// arithmetic, MT19937, or formatting are compared bit-for-bit (a == b).
//
// Sections that transit through libm transcendentals are compared with
// tolerance instead, and bit equality there is not a well-defined target:
// CPython delegates math.log / math.erf to the platform C runtime, and UCRT
// (Windows), glibc, and Go's fdlibm port each round differently — a probe of
// ~8000 inputs shows UCRT's log and erf deviate from the correctly-rounded
// value by 1-2 ulp on roughly a quarter of inputs. The tolerances follow the
// error structure:
//
//   - normInvCDF / zTwoSided: log feeds sqrt and a polynomial; its 1-2 ulp
//     error arrives as <= a few ulp of the final quantile → fewUlpEq.
//   - tail p-values (two_prop, compare): p = 2*(1 - cdf) = 1 - erf(w), where
//     the subtraction is exact, so an erf error of a few ulp at magnitude <= 1
//     becomes an ABSOLUTE error <= ~1e-15 regardless of how small p is →
//     pValueEq combines that absolute floor with the relative tolerance.
package evalsig

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"sync"
	"testing"
)

const refdataPath = "../../tests/refdata/core.json"

type section struct {
	Mode  string `json:"mode"`
	Cases []json.RawMessage `json:"cases"`
}

var (
	refOnce sync.Once
	refTab  map[string]section
	refErr  error
)

func sections(t *testing.T) map[string]section {
	t.Helper()
	refOnce.Do(func() {
		data, err := os.ReadFile(refdataPath)
		if err != nil {
			refErr = fmt.Errorf("reference table not found: %v (run tests/gen_ref_tables.py)", err)
			return
		}
		if err := json.Unmarshal(data, &refTab); err != nil {
			refErr = fmt.Errorf("bad reference table: %v", err)
		}
	})
	if refErr != nil {
		t.Skipf("%v", refErr)
	}
	return refTab
}

func casesOf(t *testing.T, name string) []json.RawMessage {
	t.Helper()
	s, ok := sections(t)[name]
	if !ok {
		t.Fatalf("section %q missing from reference table", name)
	}
	return s.Cases
}

// flex decodes a float that may carry the "nan"/"inf"/"-inf" markers.
type flex float64

func (f *flex) UnmarshalJSON(b []byte) error {
	switch string(b) {
	case `"nan"`:
		*f = flex(math.NaN())
		return nil
	case `"inf"`:
		*f = flex(math.Inf(1))
		return nil
	case `"-inf"`:
		*f = flex(math.Inf(-1))
		return nil
	}
	var v float64
	if err := json.Unmarshal(b, &v); err != nil {
		return err
	}
	*f = flex(v)
	return nil
}

func bitsEq(a, b float64) bool {
	if math.IsNaN(a) || math.IsNaN(b) {
		return math.IsNaN(a) && math.IsNaN(b)
	}
	return a == b
}

// fewUlpEq: relative tolerance covering a handful of ulp of libm divergence.
func fewUlpEq(a, b float64) bool {
	if bitsEq(a, b) {
		return true
	}
	if math.IsNaN(a) || math.IsNaN(b) || math.IsInf(a, 0) || math.IsInf(b, 0) {
		return false
	}
	if b == 0 {
		return math.Abs(a) < 1e-300
	}
	return math.Abs(a-b)/math.Abs(b) < 4e-15
}

// pValueEq: tail p-values are 2*(1-cdf), so an erf/betainc error of a few ulp
// at magnitude ~1 lands as an absolute error <= ~1e-15 in p regardless of how
// small p itself is. Observed divergences: 1-2 ulp of the intermediate cdf
// (2.2e-16 and 4.4e-16 in two_prop / compare), matching the model.
func pValueEq(a, b float64) bool {
	if bitsEq(a, b) {
		return true
	}
	if math.IsNaN(a) || math.IsNaN(b) {
		return false
	}
	d := math.Abs(a - b)
	return d <= 1e-15 || d/math.Abs(b) < 4e-15
}

func fdesc(v float64) string { return pyReprFloat(v) }

func failFloat(t *testing.T, ctx string, got, want float64, ulp bool) {
	t.Helper()
	kind := "bits"
	if ulp {
		kind = "ulp"
	}
	t.Errorf("%s: got %s, want %s (%s)", ctx, fdesc(got), fdesc(want), kind)
}

// ---------------------------------------------------------------- z / normal

func TestRefZTwoSided(t *testing.T) {
	var cases []struct {
		Alpha float64 `json:"alpha"`
		Want  float64 `json:"want"`
	}
	mustDecode(t, casesOf(t, "z_two_sided"), &cases)
	for i, c := range cases {
		if got := zTwoSided(c.Alpha); !fewUlpEq(got, c.Want) {
			failFloat(t, fmt.Sprintf("z_two_sided[%d] alpha=%v", i, c.Alpha), got, c.Want, true)
		}
	}
}

