// ---------------------------------------------------------------- intervals

func TestRefWilson(t *testing.T) {
	var cases []struct {
		S        int     `json:"s"`
		N        int     `json:"n"`
		Alpha    float64 `json:"alpha"`
		Low      float64 `json:"low"`
		High     float64 `json:"high"`
		RootsLow float64 `json:"roots_low"`
		RootsHigh float64 `json:"roots_high"`
	}
	mustDecode(t, casesOf(t, "wilson"), &cases)
	for i, c := range cases {
		w := WilsonInterval(c.S, c.N, c.Alpha)
		if !bitsEq(w.Low, c.Low) || !bitsEq(w.High, c.High) {
			failFloat(t, fmt.Sprintf("wilson[%d] %d/%d a=%v low", i, c.S, c.N, c.Alpha), w.Low, c.Low, false)
			failFloat(t, fmt.Sprintf("wilson[%d] %d/%d a=%v high", i, c.S, c.N, c.Alpha), w.High, c.High, false)
		}
		r := WilsonIntervalRoots(c.S, c.N, c.Alpha)
		if !bitsEq(r.Low, c.RootsLow) || !bitsEq(r.High, c.RootsHigh) {
			failFloat(t, fmt.Sprintf("wilsonRoots[%d] %d/%d a=%v low", i, c.S, c.N, c.Alpha), r.Low, c.RootsLow, false)
			failFloat(t, fmt.Sprintf("wilsonRoots[%d] %d/%d a=%v high", i, c.S, c.N, c.Alpha), r.High, c.RootsHigh, false)
		}
	}
}

