func TestRefTwoProportion(t *testing.T) {
	var cases []struct {
		S1    int   `json:"s1"`
		N1    int   `json:"n1"`
		S2    int   `json:"s2"`
		N2    int   `json:"n2"`
		Alpha float64 `json:"alpha"`
		Diff  float64 `json:"diff"`
		Low   float64 `json:"low"`
		High  float64 `json:"high"`
		Z     flex   `json:"z"`
		P     flex   `json:"p"`
	}
	mustDecode(t, casesOf(t, "two_prop"), &cases)
	for i, c := range cases {
		r := TwoProportionTest(c.S1, c.N1, c.S2, c.N2, c.Alpha)
		if !bitsEq(r.Diff, c.Diff) {
			failFloat(t, fmt.Sprintf("twoProp[%d] diff", i), r.Diff, c.Diff, false)
		}
		if !bitsEq(r.CI.Low, c.Low) || !bitsEq(r.CI.High, c.High) {
			failFloat(t, fmt.Sprintf("twoProp[%d] ci.low", i), r.CI.Low, c.Low, false)
			failFloat(t, fmt.Sprintf("twoProp[%d] ci.high", i), r.CI.High, c.High, false)
		}
		if !bitsEq(float64(c.Z), r.Z) {
			failFloat(t, fmt.Sprintf("twoProp[%d] z", i), r.Z, float64(c.Z), false)
		}
		if !pValueEq(r.PValue, float64(c.P)) {
			failFloat(t, fmt.Sprintf("twoProp[%d] p", i), r.PValue, float64(c.P), true)
		}
	}
}

