func TestRefMcNemar(t *testing.T) {
	var cases []struct {
		B     int     `json:"b"`
		C     int     `json:"c"`
		Alpha float64 `json:"alpha"`
		Diff  float64 `json:"diff"`
		Low   float64 `json:"low"`
		High  float64 `json:"high"`
		P     float64 `json:"p"`
	}
	mustDecode(t, casesOf(t, "mcnemar"), &cases)
	for i, c := range cases {
		m := McNemarExact(c.B, c.C, c.Alpha)
		if !bitsEq(m.Diff, c.Diff) || !bitsEq(m.PValue, c.P) {
			failFloat(t, fmt.Sprintf("mcnemar[%d] b=%d c=%d diff", i, c.B, c.C), m.Diff, c.Diff, false)
			failFloat(t, fmt.Sprintf("mcnemar[%d] b=%d c=%d p", i, c.B, c.C), m.PValue, c.P, false)
		}
		if !bitsEq(m.CI.Low, c.Low) || !bitsEq(m.CI.High, c.High) {
			failFloat(t, fmt.Sprintf("mcnemar[%d] b=%d c=%d low", i, c.B, c.C), m.CI.Low, c.Low, false)
			failFloat(t, fmt.Sprintf("mcnemar[%d] b=%d c=%d high", i, c.B, c.C), m.CI.High, c.High, false)
		}
	}
}

