// ---------------------------------------------------------------- power

func TestRefPower(t *testing.T) {
	var cases []struct {
		Kind  string  `json:"kind"`
		P1    float64 `json:"p1"`
		P2    float64 `json:"p2"`
		Disc  float64 `json:"disc"`
		Delta float64 `json:"delta"`
		Width float64 `json:"width"`
		P     float64 `json:"p"`
		Alpha float64 `json:"alpha"`
		Power float64 `json:"power"`
		N     int     `json:"n"`
	}
	mustDecode(t, casesOf(t, "power"), &cases)
	for i, c := range cases {
		var got int
		switch c.Kind {
		case "two":
			got = NTwoProportions(c.P1, c.P2, c.Alpha, c.Power).NPerVersion
		case "paired":
			got = NPaired(c.Disc, c.Delta, c.Alpha, c.Power).NPerVersion
		case "width":
			got = NForCIWidth(c.Width, c.P, c.Alpha).NPerVersion
		default:
			t.Fatalf("power[%d]: unknown kind %q", i, c.Kind)
		}
		if got != c.N {
			t.Errorf("power[%d] %s: got n=%d, want %d", i, c.Kind, got, c.N)
		}
	}
}

// ---------------------------------------------------------------- variance

func TestRefVarianceComponents(t *testing.T) {
	var cases []struct {
		Groups  [][]json.RawMessage `json:"groups"`
		Between float64             `json:"between"`
		Within  float64             `json:"within"`
		Total   float64             `json:"total"`
		ICC     float64             `json:"icc"`
	}
	mustDecode(t, casesOf(t, "variance_components"), &cases)
	for i, c := range cases {
		groups := make([]*group, 0, len(c.Groups))
		for _, g := range c.Groups {
			var name string
			var vals []float64
			if err := json.Unmarshal(g[0], &name); err != nil {
				t.Fatalf("variance[%d]: bad group name: %v", i, err)
			}
			if err := json.Unmarshal(g[1], &vals); err != nil {
				t.Fatalf("variance[%d]: bad group values: %v", i, err)
			}
			groups = append(groups, &group{key: name, vals: vals})
		}
		vc := VarianceComponentsOf(groups)
		if !bitsEq(vc.Between, c.Between) || !bitsEq(vc.Within, c.Within) ||
			!bitsEq(vc.Total, c.Total) || !bitsEq(vc.ICC, c.ICC) {
			failFloat(t, fmt.Sprintf("variance[%d] between", i), vc.Between, c.Between, false)
			failFloat(t, fmt.Sprintf("variance[%d] within", i), vc.Within, c.Within, false)
			failFloat(t, fmt.Sprintf("variance[%d] total", i), vc.Total, c.Total, false)
			failFloat(t, fmt.Sprintf("variance[%d] icc", i), vc.ICC, c.ICC, false)
		}
	}
}

// ---------------------------------------------------------------- holm

func TestRefHolm(t *testing.T) {
	var cases []struct {
		Alpha   float64          `json:"alpha"`
		Entries [][2]interface{} `json:"entries"`
		Want    [][3]interface{} `json:"want"`
	}
	mustDecode(t, casesOf(t, "holm"), &cases)
	for i, c := range cases {
		in := make([]HolmP, 0, len(c.Entries))
		for _, e := range c.Entries {
			in = append(in, HolmP{Name: toString(e[0]), P: toFloat(t, e[1])})
		}
		got := Holm(in, c.Alpha)
		if len(got) != len(c.Want) {
			t.Fatalf("holm[%d]: got %d entries, want %d", i, len(got), len(c.Want))
		}
		for j, w := range c.Want {
			if got[j].Name != toString(w[0]) {
				t.Errorf("holm[%d][%d]: name got %q want %q", i, j, got[j].Name, toString(w[0]))
			}
			if !bitsEq(got[j].Adjusted, toFloat(t, w[1])) {
				failFloat(t, fmt.Sprintf("holm[%d][%d] adj", i, j), got[j].Adjusted, toFloat(t, w[1]), false)
			}
			if got[j].Reject != toBool(w[2]) {
				t.Errorf("holm[%d][%d]: reject got %v want %v", i, j, got[j].Reject, toBool(w[2]))
			}
		}
	}
}

func toString(v interface{}) string {
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", v)
}

func toFloat(t *testing.T, v interface{}) float64 {
	t.Helper()
	switch x := v.(type) {
	case float64:
		return x
	case int:
		return float64(x)
	case json.Number:
		f, err := x.Float64()
		if err != nil {
			t.Fatalf("bad number %v", x)
		}
		return f
	}
	t.Fatalf("expected number, got %T", v)
	return 0
}

func toBool(v interface{}) bool {
	b, ok := v.(bool)
	if !ok {
		return false
	}
	return b
}

// ---------------------------------------------------------------- MT19937

func TestRefMT19937(t *testing.T) {
	var cases []struct {
		Seed int      `json:"seed"`
		Kind string   `json:"kind"`
		K    int      `json:"k"`
		Want []uint64 `json:"want"`
	}
	mustDecode(t, casesOf(t, "mt19937"), &cases)
	for i, c := range cases {
		r := &pyRandom{}
		r.seedInt(int64(c.Seed))
		var draw func() uint64
		switch {
		case c.Kind == "randrange":
			draw = nil // handled below: randrange consumes _randbelow words
		case c.Kind == "getrandbits32":
			draw = func() uint64 { return r.getrandbits(32) }
		default:
			var bits int
			if _, err := fmt.Sscanf(c.Kind, "getrandbits%d", &bits); err != nil {
				t.Fatalf("mt[%d]: bad kind %q", i, c.Kind)
			}
			draw = func() uint64 { return r.getrandbits(bits) }
		}
		got := make([]uint64, 0, len(c.Want))
		if draw == nil {
			for j := 0; j < len(c.Want); j++ {
				got = append(got, uint64(r.randrange(c.K)))
			}
		} else {
			for j := 0; j < len(c.Want); j++ {
				got = append(got, draw())
			}
		}
		if len(got) != len(c.Want) {
			t.Fatalf("mt[%d]: length %d != %d", i, len(got), len(c.Want))
		}
		for j := range got {
			if got[j] != c.Want[j] {
				t.Errorf("mt[%d] %s seed=%d [%d]: got %d, want %d", i, c.Kind, c.Seed, j, got[j], c.Want[j])
			}
		}
	}
}

