// ---------------------------------------------------------------- compare (end to end)

func TestRefCompare(t *testing.T) {
	type want struct {
		Estimate flex   `json:"estimate"`
		Low      flex   `json:"low"`
		High     flex   `json:"high"`
		P        flex   `json:"p"`
		Method   string `json:"method"`
		Paired   bool   `json:"paired"`
		Verdict  string `json:"verdict"`
		Needed   int    `json:"additional_needed"`
	}
	var cases []struct {
		Name  string          `json:"name"`
		Alpha float64         `json:"alpha"`
		RunsA json.RawMessage `json:"runs_a"`
		RunsB json.RawMessage `json:"runs_b"`
		Want  want            `json:"want"`
	}
	mustDecode(t, casesOf(t, "compare"), &cases)
	for i, c := range cases {
		ra, err := runsFromRaw(c.RunsA)
		if err != nil {
			t.Fatalf("compare[%d]: %v", i, err)
		}
		rb, err := runsFromRaw(c.RunsB)
		if err != nil {
			t.Fatalf("compare[%d]: %v", i, err)
		}
		got, err := Compare(ra, rb, "A", "B", c.Alpha)
		if err != nil {
			t.Fatalf("compare[%d]: %v", i, err)
		}
		w := c.Want
		if !bitsEq(got.Estimate, float64(w.Estimate)) {
			failFloat(t, fmt.Sprintf("compare[%d] %s estimate", i, c.Name), got.Estimate, float64(w.Estimate), false)
		}
		if !bitsEq(got.CI.Low, float64(w.Low)) || !bitsEq(got.CI.High, float64(w.High)) {
			failFloat(t, fmt.Sprintf("compare[%d] %s ci.low", i, c.Name), got.CI.Low, float64(w.Low), false)
			failFloat(t, fmt.Sprintf("compare[%d] %s ci.high", i, c.Name), got.CI.High, float64(w.High), false)
		}
		if !pValueEq(got.PValue, float64(w.P)) {
			failFloat(t, fmt.Sprintf("compare[%d] %s p", i, c.Name), got.PValue, float64(w.P), true)
		}
		if got.Method != w.Method || got.Paired != w.Paired || got.Verdict != w.Verdict || got.AdditionalNeeded != w.Needed {
			t.Errorf("compare[%d] %s: method=%q paired=%v verdict=%q needed=%d; want %q %v %q %d",
				i, c.Name, got.Method, got.Paired, got.Verdict, got.AdditionalNeeded,
				w.Method, w.Paired, w.Verdict, w.Needed)
		}
	}
}

func runsFromRaw(raw json.RawMessage) ([]Run, error) {
	v, err := parsePyJSON([]byte(raw))
	if err != nil {
		return nil, err
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, fmt.Errorf("expected array")
	}
	return runsFromArray(arr, "")
}

// ---------------------------------------------------------------- decide (end to end)

func TestRefDecide(t *testing.T) {
	var cases []struct {
		Candidates   json.RawMessage `json:"candidates"`
		Alpha        float64         `json:"alpha"`
		WantRanking  [][]interface{} `json:"want_ranking"`
		WantAdjusted [][2]interface{} `json:"want_adjusted"`
		WantVerdicts []string        `json:"want_verdicts"`
		WantMethods  []string        `json:"want_methods"`
	}
	mustDecode(t, casesOf(t, "decide"), &cases)
	for i, c := range cases {
		v, err := parsePyJSON([]byte(c.Candidates))
		if err != nil {
			t.Fatalf("decide[%d]: parse: %v", i, err)
		}
		obj, ok := v.(*pyObj)
		if !ok {
			t.Fatalf("decide[%d]: candidates not an object", i)
		}
		var cands []Candidate
		for _, kv := range obj.pairs {
			arr, ok := kv.v.([]interface{})
			if !ok {
				t.Fatalf("decide[%d]: candidate %q runs not an array", i, kv.k)
			}
			runs, err := runsFromArray(arr, "")
			if err != nil {
				t.Fatalf("decide[%d]: %v", i, err)
			}
			cands = append(cands, Candidate{Name: kv.k, Runs: runs})
		}
		rep, err := Decide(cands, c.Alpha)
		if err != nil {
			t.Fatalf("decide[%d]: %v", i, err)
		}
		for j, w := range c.WantRanking {
			name := toString(w[0])
			if rep.Ranking[j].Name != name {
				t.Errorf("decide[%d] ranking[%d]: name got %q want %q", i, j, rep.Ranking[j].Name, name)
			}
			if !bitsEq(rep.Ranking[j].Estimate, toFloat(t, w[1])) {
				failFloat(t, fmt.Sprintf("decide[%d] ranking[%d] %s est", i, j, name),
					rep.Ranking[j].Estimate, toFloat(t, w[1]), false)
			}
			if rep.Ranking[j].Action != toString(w[2]) {
				t.Errorf("decide[%d] ranking[%d] %s: action got %q want %q", i, j, name,
					rep.Ranking[j].Action, toString(w[2]))
			}
		}
		for j, w := range c.WantAdjusted {
			// w[1] is Python's repr of the adjusted p — compare via repr
			if rep.Adjusted[j].Name != toString(w[0]) || pyReprFloat(rep.Adjusted[j].Adjusted) != toString(w[1]) {
				t.Errorf("decide[%d] adjusted[%d]: got %q %s, want %q %s", i, j,
					rep.Adjusted[j].Name, pyReprFloat(rep.Adjusted[j].Adjusted), toString(w[0]), toString(w[1]))
			}
		}
		if len(rep.Comparisons) != len(c.WantVerdicts) {
			t.Fatalf("decide[%d]: %d comparisons, want %d", i, len(rep.Comparisons), len(c.WantVerdicts))
		}
		for j, cmp := range rep.Comparisons {
			if cmp.Verdict != c.WantVerdicts[j] || cmp.Method != c.WantMethods[j] {
				t.Errorf("decide[%d] comparison[%d]: verdict=%q method=%q; want %q %q",
					i, j, cmp.Verdict, cmp.Method, c.WantVerdicts[j], c.WantMethods[j])
			}
		}
	}
}

// ---------------------------------------------------------------- sequential

func TestRefSequential(t *testing.T) {
	var cases []struct {
		Kind      string       `json:"kind"`
		Alpha     float64      `json:"alpha"`
		Half      float64      `json:"half"`
		Steps     [][]float64  `json:"steps"`
		Verdicts  []string     `json:"verdicts"`
		LooksUsed int          `json:"looks_used"`
	}
	mustDecode(t, casesOf(t, "sequential"), &cases)
	for i, c := range cases {
		if len(c.Steps) != len(c.Verdicts) {
			t.Fatalf("sequential[%d]: steps/verdicts length mismatch", i)
		}
		if c.Kind == "prop" {
			sp := NewSequentialProportion(c.Alpha, c.Half)
			for j, st := range c.Steps {
				if got := sp.Update(int(st[0]), int(st[1])); got != c.Verdicts[j] {
					t.Errorf("sequential[%d] step %d: verdict got %q want %q", i, j, got, c.Verdicts[j])
				}
			}
			if sp.LooksUsed != c.LooksUsed {
				t.Errorf("sequential[%d]: looks_used got %d want %d", i, sp.LooksUsed, c.LooksUsed)
			}
		} else {
			ab := NewSequentialAB(c.Alpha, c.Half)
			for j, st := range c.Steps {
				if got := ab.Update(int(st[0]), int(st[1]), int(st[2]), int(st[3])); got != c.Verdicts[j] {
					t.Errorf("sequential[%d] step %d: verdict got %q want %q", i, j, got, c.Verdicts[j])
				}
			}
			if ab.LooksUsed != c.LooksUsed {
				t.Errorf("sequential[%d]: looks_used got %d want %d", i, ab.LooksUsed, c.LooksUsed)
			}
		}
	}
}

// ---------------------------------------------------------------- panic parity

// The Python reference raises StatisticsError when every cluster in a
// bootstrap resample is empty; the Go port panics with the same message. With
// k=2 clusters of which one is empty, a quarter of seeds hit the all-empty
// resample, so this pins the error path too.
func TestClusterBootstrapAllEmptyResamplePanics(t *testing.T) {
	defer func() {
		if r := recover(); r == nil {
			t.Fatalf("expected panic on all-empty resample")
		}
	}()
	clusters := [][]float64{{1.0, 2.0}, {}}
	ClusterBootstrapCI(clusters, nil, 4, 0.05, 0)
}

// The Python reference raises ValueError("n must be >= 1, ...") on zero sample
// size; the Go port panics with the same message instead of dividing to NaN.
func TestZeroNPanics(t *testing.T) {
	for _, tc := range []struct {
		name string
		fn   func()
	}{
		{"two_proportion n1=0", func() { TwoProportionTest(0, 0, 5, 10, 0.05) }},
		{"two_proportion n2=0", func() { TwoProportionTest(5, 10, 0, 0, 0.05) }},
		{"sequential update n=0", func() { NewSequentialProportion(0.05, 0.05).Update(0, 0) }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			defer func() {
				r := recover()
				if r == nil {
					t.Fatalf("expected panic, got none")
				}
				if msg, ok := r.(string); ok && msg != "n must be >= 1, got 0" {
					t.Fatalf("panic message: got %q, want %q", msg, "n must be >= 1, got 0")
				}
			}()
			tc.fn()
		})
	}
}

func mustDecode(t *testing.T, raws []json.RawMessage, dst interface{}) {
	t.Helper()
	if err := json.Unmarshal(mustJoin(raws), dst); err != nil {
		t.Fatalf("decode reference cases: %v", err)
	}
}

func mustJoin(raws []json.RawMessage) []byte {
	var b bytes.Buffer
	b.WriteByte('[')
	for i, r := range raws {
		if i > 0 {
			b.WriteByte(',')
		}
		b.Write(r)
	}
	b.WriteByte(']')
	return b.Bytes()
}
